func Open[P any](ctx context.Context, config Config[P]) (*App[P], error) {
	return golemOpen(ctx, config, golemruntime.Config[P, Actor]{Database: config.Database})
}

func golemOpen[P any](ctx context.Context, config Config[P], engineConfig golemruntime.Config[P, Actor]) (*App[P], error) {
	bindings, err := GolemGeneratedApplicationBindings()
	if err != nil {
		return nil, err
	}
	descriptors, err := GolemGeneratedApplicationDescriptors()
	if err != nil {
		return nil, err
	}
	eventRegistry := golem.EventRegistry{}
	eventFactories := golemruntime.EventFactoryRegistry{}
	engineConfig.Bundle = GolemGeneratedSchemaBundle()
	engineConfig.Bindings = bindings
	engineConfig.Descriptors = descriptors
	engineConfig.Embeddings = config.Embeddings
	engineConfig.ReadLimits = config.ReadLimits
	engineConfig.MutationLimits = config.MutationLimits
	engineConfig.AnalyticsLimits = config.AnalyticsLimits
	engineConfig.EventRegistry = eventRegistry
	engineConfig.EventFactories = eventFactories
	engineConfig.EventLimits = config.EventLimits
	engineConfig.EventTransport = config.EventTransport
	engineConfig.Observer = config.Observer
	engineConfig.CDCAdapters = config.CDCAdapters
	engineConfig.ReportEventOperator = config.ReportEventOperator
	engineConfig.HistoricalEventBundles = config.HistoricalEventBundles
	engineConfig.AfterCommitError = config.AfterCommitError
	engineConfig.AuditPrincipal = config.AuditPrincipal
	engineConfig.ReportScopedQuery = config.ReportScopedQuery
	engineConfig.ResolvePrincipal = config.ResolvePrincipal
	engineConfig.SnapshotPrincipal = config.SnapshotPrincipal
	engineConfig.SnapshotActor = config.SnapshotActor
	engine, err := golemruntime.Open(ctx, engineConfig)
	if err != nil {
		return nil, err
	}
	return &App[P]{runtime: engine, observer: config.Observer, provider: config.Database.Provider()}, nil
}

func (app *App[P]) RunEventPublisher(ctx context.Context) error {
	if app == nil {
		return events.Failure(events.CodeEventConfig)
	}
	return app.runtime.RunEventPublisher(ctx)
}
func (app *App[P]) RefreshSemanticIndexes(ctx context.Context) error {
	if app == nil {
		return fmt.Errorf("P9_SEMANTIC_RUNTIME: application is required")
	}
	return app.runtime.RefreshSemanticIndexes(ctx)
}
func (app *App[P]) EventCapabilities() events.Capabilities {
	if app == nil {
		return events.Capabilities{}
	}
	return app.runtime.EventCapabilities()
}
func (app *App[P]) EventOperator() events.Operator {
	if app == nil {
		return nil
	}
	return app.runtime.EventOperator()
}
func (app *App[P]) EventLimits() events.Limits {
	if app == nil {
		return events.Limits{}
	}
	return app.runtime.EventLimits()
}

func (app *App[P]) ForPrincipal(ctx context.Context, principal P) (*Caller[P], error) {
	inner, err := app.runtime.ForPrincipal(ctx, principal)
	if err != nil {
		return nil, err
	}
	result := &Caller[P]{runtime: inner}
	result.Users = CallerUserClient[P]{runtime: inner}
	result.PostTags = CallerPostTagClient[P]{runtime: inner}
	result.Posts = CallerPostClient[P]{runtime: inner}
	result.Friendships = CallerFriendshipClient[P]{runtime: inner}
	result.Tags = CallerTagClient[P]{runtime: inner}
	result.Comments = CallerCommentClient[P]{runtime: inner}
	return result, nil
}

func (app *App[P]) System() System[P] {
	inner := app.runtime.System()
	result := System[P]{runtime: inner}
	result.Users = SystemUserClient[P]{runtime: inner}
	result.PostTags = SystemPostTagClient[P]{runtime: inner}
	result.Posts = SystemPostClient[P]{runtime: inner}
	result.Friendships = SystemFriendshipClient[P]{runtime: inner}
	result.Tags = SystemTagClient[P]{runtime: inner}
	result.Comments = SystemCommentClient[P]{runtime: inner}
	return result
}

func (caller *Caller[P]) Transaction(ctx context.Context, callback func(*CallerTx[P]) error) error {
	if caller == nil {
		return golemruntime.CallerTransaction(ctx, (*golemruntime.Caller[P, Actor])(nil), nil)
	}
	if callback == nil {
		return golemruntime.CallerTransaction(ctx, caller.runtime, nil)
	}
	return golemruntime.CallerTransaction(ctx, caller.runtime, func(inner *golemruntime.CallerTx[P, Actor]) error {
		result := &CallerTx[P]{runtime: inner}
		result.Users = CallerTxUserClient[P]{runtime: inner}
		result.PostTags = CallerTxPostTagClient[P]{runtime: inner}
		result.Posts = CallerTxPostClient[P]{runtime: inner}
		result.Friendships = CallerTxFriendshipClient[P]{runtime: inner}
		result.Tags = CallerTxTagClient[P]{runtime: inner}
		result.Comments = CallerTxCommentClient[P]{runtime: inner}
		return callback(result)
	})
}

func (system System[P]) Transaction(ctx context.Context, callback func(*SystemTx[P]) error) error {
	if callback == nil {
		return golemruntime.SystemTransaction(ctx, system.runtime, nil)
	}
	return golemruntime.SystemTransaction(ctx, system.runtime, func(inner *golemruntime.SystemTx[P, Actor]) error {
		result := &SystemTx[P]{runtime: inner}
		result.Users = SystemTxUserClient[P]{runtime: inner}
		result.PostTags = SystemTxPostTagClient[P]{runtime: inner}
		result.Posts = SystemTxPostClient[P]{runtime: inner}
		result.Friendships = SystemTxFriendshipClient[P]{runtime: inner}
		result.Tags = SystemTxTagClient[P]{runtime: inner}
		result.Comments = SystemTxCommentClient[P]{runtime: inner}
		return callback(result)
	})
}
